    Float u1 = 2 * u.x - 1;
    Float u2 = 2 * u.y - 1;

    // Handle degeneracy at the origin
    if (u1 == 0 && u2 == 0) return Point2f(0, 0);

    Float r, theta;

    // Apply concentric mapping
    if (std::abs(u1) > std::abs(u2)) {
        r = u1;
        theta = (Pi / 4.0) * (u2 / u1);
    } else {
        r = u2;
        theta = (Pi / 2.0) - (Pi / 4.0) * (u1 / u2);
    }

    return r * Point2f(std::cos(theta), std::sin(theta));

